    async saveBankAccount(){this.bankAccountFormError='';if(!this.bankAccountForm.itemName?.trim()||!this.bankAccountForm.paymentName?.trim()||!this.bankAccountForm.accountNo?.trim()){this.bankAccountFormError='請完整填寫項目、付款名稱和帳戶';return}this.bankAccountSaving=true;try{const payload={...this.bankAccountForm};if(this.editingBankAccount){await updateAdminPropertyBankAccount(this.property.ownerId,this.property.ownerUnitId,this.editingBankAccount.id,payload)}else{await createAdminPropertyBankAccount(this.property.ownerId,this.property.ownerUnitId,payload)}this.closeBankAccountForm();await this.loadBankAccounts();this.$root?.showToast?.('銀行帳戶已儲存')}catch(error){this.bankAccountFormError=error.message||'銀行帳戶儲存失敗'}finally{this.bankAccountSaving=false}},
    async removeBankAccount(item){if(!confirm(`確定刪除銀行帳戶「${item.itemName} · ${item.accountNo}」？刪除後無法恢復。`))return;try{await deleteAdminPropertyBankAccount(this.property.ownerId,this.property.ownerUnitId,item.id);await this.loadBankAccounts();this.$root?.showToast?.('銀行帳戶已刪除')}catch(error){this.$root?.showToast?.(error.message||'銀行帳戶刪除失敗')}},
    async openRentalWorkspace(lease){this.rentalModalOpen=true;this.rentalActiveTab='lease';this.selectedRental={...lease};this.rentalError='';this.rentalDetailLoading=true;this.resetRentalPhotoEditor();try{if(!this.photoLoaded)await this.loadPhotos();const [tenancy,collections]=await Promise.all([fetchAdminTenancy({keyword:lease.leaseNo,page:1,pageSize:100}),fetchAdminRentCollections({keyword:lease.leaseNo,page:1,pageSize:100}),this.loadRentalPhotos(lease.leaseId)]);const detail=(tenancy.rows||[]).find(row=>String(row.leaseId)===String(lease.leaseId))||{};this.selectedRental={...lease,...detail};this.rentalLeaseForm={startDate:detail.leaseStart||lease.startDate||'',endDate:detail.leaseEnd||lease.endDate||'',monthlyRent:Number(detail.monthlyRent??lease.monthlyRent??0),depositAmount:Number(detail.depositAmount??lease.depositAmount??0),paymentDay:Number(detail.paymentDay??lease.paymentDay??1)};this.rentalTenantForm={fullName:detail.tenantName||lease.tenantName||'',identityNo:detail.identityNo||'',phone:detail.phone||'',email:detail.email||'',status:detail.tenantStatus||'active'};this.rentalRentRows=(collections.rows||[]).filter(row=>String(row.leaseId)===String(lease.leaseId))}catch(error){this.rentalError=error.message||'代租管資料載入失敗'}finally{this.rentalDetailLoading=false}},
    closeRentalWorkspace(){this.rentalModalOpen=false;this.selectedRental=null;this.rentalContractFile=null;this.rentalError='';this.resetRentalPhotoEditor()},
    switchRentalTab(key){this.rentalActiveTab=key;this.rentalError='';this.resetRentalPhotoEditor();if(key==='cashflow')this.loadRentalCashflows()},
    async saveRentalLease(){this.rentalError='';if(this.rentalLeaseForm.endDate<this.rentalLeaseForm.startDate){this.rentalError='租約結束日期不可早於開始日期';return}this.rentalSaving=true;try{await updateAdminLease(this.selectedRental.leaseId,{...this.rentalLeaseForm,monthlyRent:Number(this.rentalLeaseForm.monthlyRent),depositAmount:Number(this.rentalLeaseForm.depositAmount),paymentDay:Number(this.rentalLeaseForm.paymentDay)});if(this.rentalContractFile)await uploadAdminLeaseContract(this.selectedRental.leaseId,this.rentalContractFile);const leaseId=this.selectedRental.leaseId;await this.refreshContracts();const lease=this.leaseOptions.find(item=>String(item.leaseId)===String(leaseId))||this.selectedRental;await this.openRentalWorkspace(lease);this.$root?.showToast?.('租約資料已儲存')}catch(error){this.rentalError=error.message||'租約資料儲存失敗'}finally{this.rentalSaving=false}},
    async saveRentalTenant(){this.rentalError='';this.rentalSaving=true;try{await updateAdminTenant(this.selectedRental.tenantId,{...this.rentalTenantForm,status:this.rentalTenantForm.status||'active'});const current={...this.selectedRental,tenantName:this.rentalTenantForm.fullName};await this.openRentalWorkspace(current);this.rentalActiveTab='tenant';this.$root?.showToast?.('租客資料已儲存')}catch(error){this.rentalError=error.message||'租客資料儲存失敗'}finally{this.rentalSaving=false}},
    async downloadRentalContract(){try{const result=await fetchAdminLeaseContract(this.selectedRental.leaseId,true),url=URL.createObjectURL(result.blob),link=document.createElement('a');link.href=url;link.download=this.selectedRental.contractDocumentName||`${this.selectedRental.leaseNo}.pdf`;document.body.appendChild(link);link.click();link.remove();URL.revokeObjectURL(url)}catch(error){this.rentalError=error.message||'租約附件下載失敗'}},
    async loadRentalCashflows(){if(!this.selectedRental)return;try{const [invoices,payments]=await Promise.all([fetchAdminRentCollections({keyword:this.selectedRental.leaseNo,page:1,pageSize:100}),fetchAdminLeasePayments(this.selectedRental.leaseId)]);this.rentalRentRows=(invoices.rows||[]).filter(row=>String(row.leaseId)===String(this.selectedRental.leaseId));this.rentalPayments=payments||[]}catch(error){this.rentalError=error.message||'租金收支載入失敗'}},
    openRentalPaymentEditor(payment=null,invoice=null){this.editingRentalPayment=payment;this.rentalPaymentProof=null;this.rentalPaymentError='';const target=invoice||(!payment?this.rentalRentRows[0]:null);this.rentalPaymentForm={invoiceId:payment?.invoiceId||target?.invoiceId||'',amount:Number(payment?.amount??target?.outstandingAmount??0),paymentDate:payment?.paymentDate||new Date().toISOString().slice(0,10),paymentMethod:payment?.paymentMethod||'bank_transfer',payerName:payment?.payerName||this.selectedRental?.tenantName||'',paymentReference:payment?.paymentReference||'',note:payment?.note||''};this.rentalPaymentEditorOpen=true},
    closeRentalPaymentEditor(){this.rentalPaymentEditorOpen=false;this.editingRentalPayment=null;this.rentalPaymentProof=null;this.rentalPaymentError='';if(this.$refs.rentalPaymentProofInput)this.$refs.rentalPaymentProofInput.value=''},
    applyRentalInvoice(){const invoice=this.rentalRentRows.find(row=>String(row.invoiceId)===String(this.rentalPaymentForm.invoiceId));if(invoice)this.rentalPaymentForm.amount=Number(invoice.outstandingAmount||0)},
    async saveRentalPayment(){this.rentalPaymentError='';if(this.rentalPaymentForm.paymentMethod!=='cash'&&!this.rentalPaymentForm.paymentReference?.trim()){this.rentalPaymentError='非現金收款必須填寫付款參考號';return}const editing=Boolean(this.editingRentalPayment);this.rentalPaymentSaving=true;try{const payload={amount:Number(this.rentalPaymentForm.amount),paymentDate:this.rentalPaymentForm.paymentDate,paymentMethod:this.rentalPaymentForm.paymentMethod,payerName:this.rentalPaymentForm.payerName||null,paymentReference:this.rentalPaymentForm.paymentReference||null,note:this.rentalPaymentForm.note||null};if(editing){await updateAdminLeasePayment(this.selectedRental.leaseId,this.editingRentalPayment.paymentId,payload);if(this.rentalPaymentProof)await uploadAdminRentProof(this.editingRentalPayment.financeRecordId,this.rentalPaymentProof)}else{await confirmAdminRentCollection(this.rentalPaymentForm.invoiceId,payload,this.rentalPaymentProof)}this.closeRentalPaymentEditor();await this.loadRentalCashflows();this.cashflowLoaded=false;this.$root?.showToast?.(editing?'租金收款已修改':'租金收款已入帳')}catch(error){this.rentalPaymentError=error.message||'租金收款儲存失敗'}finally{this.rentalPaymentSaving=false}},
    async removeRentalPayment(payment){if(!confirm(`確定作廢租金收款「${payment.transactionNo}」？帳單已收金額將自動回沖。`))return;try{await deleteAdminLeasePayment(this.selectedRental.leaseId,payment.paymentId);await this.loadRentalCashflows();this.cashflowLoaded=false;this.$root?.showToast?.('租金收款已作廢並回沖')}catch(error){this.rentalPaymentError=error.message||'租金收款作廢失敗'}},
    editRentalPhoto(photo){this.editingRentalPhoto=photo;this.rentalPhotoFile=null;this.rentalPhotoError='';this.rentalPhotoForm={title:photo.title||'',description:photo.description||''}},
    resetRentalPhotoEditor(){this.editingRentalPhoto=null;this.rentalPhotoFile=null;this.rentalPhotoError='';this.rentalPhotoForm={title:'',description:''};if(this.$refs.rentalPhotoInput)this.$refs.rentalPhotoInput.value=''},
    async saveRentalPhoto(){this.rentalPhotoError='';if(this.rentalPhotoFile&&this.rentalPhotoFile.size>10*1024*1024){this.rentalPhotoError='照片不可超過 10 MB';return}this.rentalPhotoSaving=true;try{const payload={title:this.rentalPhotoForm.title,category:'other',description:this.rentalPhotoForm.description,sortOrder:0,cover:false,leaseId:this.selectedRental.leaseId,rentalStage:this.rentalActiveTab};if(this.editingRentalPhoto)await updateAdminPropertyPhoto(this.property.ownerId,this.property.ownerUnitId,this.editingRentalPhoto.id,payload,this.rentalPhotoFile);else await createAdminPropertyPhoto(this.property.ownerId,this.property.ownerUnitId,payload,this.rentalPhotoFile);await this.loadRentalPhotos(this.selectedRental.leaseId);this.resetRentalPhotoEditor();this.$root?.showToast?.('租約照片已儲存')}catch(error){this.rentalPhotoError=error.message||'租約照片儲存失敗'}finally{this.rentalPhotoSaving=false}},
    async removeRentalPhoto(photo){if(!confirm(`確定刪除照片「${photo.title}」？`))return;try{await deleteAdminPropertyPhoto(this.property.ownerId,this.property.ownerUnitId,photo.id);await this.loadRentalPhotos(this.selectedRental.leaseId);this.$root?.showToast?.('租約照片已刪除')}catch(error){this.rentalPhotoError=error.message||'照片刪除失敗'}},
    async loadCashflows(){if(!this.property)return;this.cashflowLoading=true;try{this.cashflows=await fetchAdminPropertyCashflows(this.property.ownerId,this.property.ownerUnitId)||[];this.cashflowLoaded=true}catch(error){this.$root?.showToast?.(error.message||'收支記錄載入失敗')}finally{this.cashflowLoading=false}},
    openCashflowForm(item=null){if(item&&!item.editable)return;this.editingCashflow=item;this.cashflowFile=null;this.cashflowFormError='';this.cashflowForm={direction:item?.direction||'expense',category:item?.category||'other',description:item?.description||'',amount:Number(item?.amount||0),occurredOn:item?.occurredOn||new Date().toISOString().slice(0,10),paymentMethod:item?.paymentMethod||'bank_transfer',confirmationStatus:item?.confirmationStatus||'confirmed'};this.cashflowFormOpen=true},
    closeCashflowForm(){this.cashflowFormOpen=false;this.editingCashflow=null;this.cashflowFile=null;this.cashflowFormError=''},
    async saveCashflow(){this.cashflowFormError='';if(!this.cashflowForm.description?.trim()){this.cashflowFormError='請填寫收支摘要';return}if(Number(this.cashflowForm.amount)<=0){this.cashflowFormError='收支金額必須大於 0';return}if(this.cashflowFile&&this.cashflowFile.size>15*1024*1024){this.cashflowFormError='收支憑證不可超過 15 MB';return}this.cashflowSaving=true;try{const payload={...this.cashflowForm,amount:Number(this.cashflowForm.amount)};if(this.editingCashflow){await updateAdminPropertyCashflow(this.property.ownerId,this.property.ownerUnitId,this.editingCashflow.id,payload,this.cashflowFile)}else{await createAdminPropertyCashflow(this.property.ownerId,this.property.ownerUnitId,payload,this.cashflowFile)}this.closeCashflowForm();await this.loadCashflows();this.$root?.showToast?.('收支記錄已儲存')}catch(error){this.cashflowFormError=error.message||'收支記錄儲存失敗'}finally{this.cashflowSaving=false}},
    async removeCashflow(item){if(!item.editable)return;if(!confirm(`確定刪除收支記錄「${item.description}」？刪除後無法恢復。`))return;try{await deleteAdminPropertyCashflow(this.property.ownerId,this.property.ownerUnitId,item.id);await this.loadCashflows();this.$root?.showToast?.('收支記錄已刪除')}catch(error){this.$root?.showToast?.(error.message||'收支記錄刪除失敗')}},
    async downloadCashflowProof(item){try{const result=await downloadAdminPropertyCashflowProof(this.property.ownerId,this.property.ownerUnitId,item.id),url=URL.createObjectURL(result.blob),link=document.createElement('a');link.href=url;link.download=item.attachmentName||`cashflow-${item.id}`;document.body.appendChild(link);link.click();link.remove();URL.revokeObjectURL(url)}catch(error){this.$root?.showToast?.(error.message||'收支憑證下載失敗')}},
    cashflowCategoryLabel(value){return this.cashflowCategories.find(option=>option.value===value)?.label||value||'其他'},
    cashflowSourceLabel(value){return({manual:'人工登記',rent:'租約收租',maintenance:'修繕結算',system:'系統流水'})[value]||'系統流水'},
    cashflowPaymentLabel(value){return({bank_transfer:'銀行轉帳',online_payment:'線上付款',cash:'現金',reserve_account:'預備金',other:'其他'})[value]||value||'—'},
    async loadMaintenance(){if(!this.property)return;this.maintenanceLoading=true;try{this.maintenanceRecords=await fetchAdminPropertyMaintenance(this.property.ownerId,this.property.ownerUnitId)||[];this.maintenanceLoaded=true}catch(error){this.$root?.showToast?.(error.message||'維護記錄載入失敗')}finally{this.maintenanceLoading=false}},
    openMaintenanceForm(record=null){this.editingMaintenance=record;this.maintenanceFormError='';this.maintenanceForm={category:record?.category||'other',title:record?.title||'',maintenanceDate:record?.maintenanceDate||new Date().toISOString().slice(0,10),durationMinutes:Number(record?.durationMinutes||0),details:record?.details||'',resultSummary:record?.resultSummary||'',nextMaintenanceDate:record?.nextMaintenanceDate||''};this.maintenanceFormOpen=true},
    closeMaintenanceForm(){this.maintenanceFormOpen=false;this.editingMaintenance=null;this.maintenanceFormError=''},
    async saveMaintenance(){this.maintenanceSaving=true;this.maintenanceFormError='';try{const payload={...this.maintenanceForm,durationMinutes:Number(this.maintenanceForm.durationMinutes||0),nextMaintenanceDate:this.maintenanceForm.nextMaintenanceDate||null};if(this.editingMaintenance){await updateAdminPropertyMaintenance(this.property.ownerId,this.property.ownerUnitId,this.editingMaintenance.id,payload)}else{await createAdminPropertyMaintenance(this.property.ownerId,this.property.ownerUnitId,payload)}this.closeMaintenanceForm();await this.loadMaintenance();this.$root?.showToast?.('維護記錄已儲存')}catch(error){this.maintenanceFormError=error.message||'維護記錄儲存失敗'}finally{this.maintenanceSaving=false}},
    async removeMaintenance(record){if(!confirm(`確定刪除維護記錄「${record.title}」？`))return;try{await deleteAdminPropertyMaintenance(this.property.ownerId,this.property.ownerUnitId,record.id);await this.loadMaintenance();this.$root?.showToast?.('維護記錄已刪除')}catch(error){this.$root?.showToast?.(error.message||'維護記錄刪除失敗')}},
    async loadRepairReports(){if(!this.property)return;this.repairLoading=true;try{const [records,options]=await Promise.all([fetchAdminPropertyRepairReports(this.property.ownerId,this.property.ownerUnitId),fetchAdminMaintenanceOptions()]);this.repairReports=records||[];this.maintenanceVendors=options.vendors||[];this.repairLoaded=true}catch(error){this.$root?.showToast?.(error.message||'修繕報告載入失敗')}finally{this.repairLoading=false}},
    goVendorManagement(){this.vendorManagementOpen=true},
    closeVendorManagement(){this.vendorManagementOpen=false;this.selectMenu({key:'repairReport'})},
    openRepairReportForm(record=null){this.editingRepairReport=record;this.repairReportFormError='';this.repairReportForm={unitId:this.property.unitId,vendorId:record?.vendorId||'',category:record?.category||'plumbing',title:record?.title||'',description:record?.description||'',requestedAt:this.toDateTimeLocal(record?.requestedAt||new Date()),status:record?.status||'submitted'};this.repairReportFormOpen=true},
    closeRepairReportForm(){this.repairReportFormOpen=false;this.editingRepairReport=null;this.repairReportFormError=''},
    async saveRepairReport(){this.repairReportSaving=true;this.repairReportFormError='';try{const payload={...this.repairReportForm,unitId:this.property.unitId,vendorId:this.repairReportForm.vendorId?Number(this.repairReportForm.vendorId):null,requestedAt:this.repairReportForm.requestedAt?.length===16?`${this.repairReportForm.requestedAt}:00`:this.repairReportForm.requestedAt};if(this.editingRepairReport){await updateAdminPropertyRepairReport(this.property.ownerId,this.property.ownerUnitId,this.editingRepairReport.id,payload)}else{await createAdminPropertyRepairReport(this.property.ownerId,this.property.ownerUnitId,payload)}this.closeRepairReportForm();await this.loadRepairReports();this.$root?.showToast?.('修繕報告已儲存')}catch(error){this.repairReportFormError=error.message||'修繕報告儲存失敗'}finally{this.repairReportSaving=false}},
    async removeRepairReport(record){if(!this.maintenanceDeletable(record))return;if(!confirm(`確定刪除修繕報告「${record.title}」？`))return;try{await deleteAdminPropertyRepairReport(this.property.ownerId,this.property.ownerUnitId,record.id);await this.loadRepairReports();this.$root?.showToast?.('修繕報告已刪除')}catch(error){this.$root?.showToast?.(error.message||'修繕報告刪除失敗')}},
    maintenanceEditable(record){return Boolean(record)&&!['completed','cancelled'].includes(record.status)},
    maintenanceDeletable(record){return Boolean(record)&&record.status!=='completed'&&!record.cashflowEntryId},
    maintenanceCategoryLabel(value){return this.maintenanceCategories.find(option=>option.value===value)?.label||value},
    maintenanceStatusLabel(value){return this.maintenanceStatuses.find(option=>option.value===value)?.label||value},
    toDateTimeLocal(value){const date=value instanceof Date?value:new Date(value);if(Number.isNaN(date.getTime()))return'';const offset=date.getTimezoneOffset()*60000;return new Date(date.getTime()-offset).toISOString().slice(0,16)},
    formatDateTime(value){if(!value)return'—';return String(value).replace('T',' ').slice(0,16)},
    durationLabel(value){const minutes=Number(value||0),hours=Math.floor(minutes/60),rest=minutes%60;return hours?`${hours} 小時${rest?` ${rest} 分鐘`:''}`:`${rest} 分鐘`},
    async openMaintenanceHandling(record,readOnly=true){this.handlingReadOnly=readOnly;this.handlingRecord=record;this.maintenanceHandlingOpen=true;this.handlingLoading=true;this.handlingError='';this.handlingFiles={before:[],after:[],invoice:[]};this.handlingForm={actualAmount:Number(record.actualAmount??0),settlementMethod:'reserve',completionNote:''};try{const detailPromise=fetchAdminMaintenanceDetail(record.id);const handlingPromise=!readOnly&&this.maintenanceEditable(record)?fetchAdminMaintenanceHandling(record.id):Promise.resolve({});const [detail,info]=await Promise.all([detailPromise,handlingPromise]);this.handlingDetail=detail||{attachments:[],history:[]};this.handlingInfo=info||{};if(!this.handlingInfo.reserveAccountAvailable||this.handlingReserveShortage>0)this.handlingForm.settlementMethod='direct_payment'}catch(error){this.handlingError=error.message||'工單資料讀取失敗'}finally{this.handlingLoading=false}},
    closeMaintenanceHandling(){this.maintenanceHandlingOpen=false;this.handlingRecord=null;this.handlingError=''},
    setMaintenanceHandlingFiles(type,event){const selected=Array.from(event.target.files||[]),current=this.handlingFiles[type]||[],merged=[...current,...selected].filter((file,index,files)=>files.findIndex(item=>item.name===file.name&&item.size===file.size&&item.lastModified===file.lastModified)===index);if(merged.length>6)this.handlingError='每類最多選擇 6 份文件';else if(this.handlingError==='每類最多選擇 6 份文件')this.handlingError='';this.handlingFiles[type]=merged.slice(0,6)},
    async submitMaintenanceHandling(){if(!this.handlingRecord)return;const hasBefore=Number(this.handlingInfo.beforePhotoCount||0)>0||this.handlingFiles.before.length>0,hasAfter=Number(this.handlingInfo.afterPhotoCount||0)>0||this.handlingFiles.after.length>0;if(!hasBefore||!hasAfter){this.handlingError='維修前與維修後照片各至少需要一張';return}if(this.handlingForm.settlementMethod==='reserve'&&this.handlingReserveShortage>0){this.handlingError='預備金不足，請改用直接支付';return}this.handlingSaving=true;this.handlingError='';try{if(this.handlingFiles.before.length)await uploadAdminMaintenancePhotos(this.handlingRecord.id,'before_photo',this.handlingFiles.before);if(this.handlingFiles.after.length)await uploadAdminMaintenancePhotos(this.handlingRecord.id,'after_photo',this.handlingFiles.after);if(this.handlingFiles.invoice.length)await uploadAdminMaintenancePhotos(this.handlingRecord.id,'invoice',this.handlingFiles.invoice);await completeAdminMaintenance(this.handlingRecord.id,{actualAmount:Number(this.handlingForm.actualAmount),settlementMethod:this.handlingForm.settlementMethod,completionNote:this.handlingForm.completionNote});this.closeMaintenanceHandling();await Promise.all([this.loadRepairReports(),this.loadMaintenance()]);this.$root?.showToast?.('修繕報告已完成，收支與維護記錄已同步')}catch(error){this.handlingError=error.message||'修繕報告處理失敗'}finally{this.handlingSaving=false}},
    async openMaintenanceAttachment(file){try{const result=await fetchAdminMaintenanceAttachment(file.documentId,false),url=URL.createObjectURL(result.blob),link=document.createElement('a');link.href=url;link.target='_blank';link.rel='noopener';document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),60000)}catch(error){this.$root?.showToast?.(error.message||'附件讀取失敗')}},
    attachmentTypeLabel(value){return({before_photo:'維修前',after_photo:'維修後',invoice:'發票／收據'})[value]||'附件'},
    contractTypeLabel(value){return this.contractTypes.find(x=>x.value===value)?.label||value}, goBack(){navigate('/admin/properties')}, money(v){return Number(v||0).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2})}, statusLabel(v){return({draft:'草稿',pending_review:'待審核',active:'使用中',suspended:'暫停',terminated:'已終止',completed:'已完成',cancelled:'已取消'})[v]||v}
  }
};
</script>

